{
  "name": "Newport 8742 皮米电机控制器",
  "name_en": "Newport 8742 Picomotor Controller",
  "manufacturer": "Newport",
  "description": "这是一款用于驱动 Newport Picomotor 微位移电机的多轴运动控制器，可通过以太网或 USB 连接，并支持 RS-485 多控制器组网。它常用于光学平台、精密定位机构和对准系统中的高分辨率位置调节与微小位移控制。",
  "description_en": "This is a multi-axis motion controller for Newport Picomotor actuators. It can communicate over Ethernet or USB and supports RS-485 multi-controller networking. It is commonly used for high-resolution positioning and fine alignment in optical setups, precision positioning assemblies, and adjustment systems.",
  "tag_hints": [
    "picomotor control",
    "precision motion control",
    "multi-axis positioning",
    "optical alignment",
    "micro-positioning",
    "RS-485 multi-controller network",
    "Ethernet instrument control",
    "USB motion controller"
  ],
  "actions": [
    {
      "action_name": "auto-axis",
      "description": "选择或访问某个电机轴通道。",
      "description_en": "Select or access a motor axis channel."
    },
    {
      "action_name": "auto-controller_address",
      "description": "获取/设置控制器地址。",
      "description_en": "Get/set the controller address."
    },
    {
      "action_name": "auto-controller_configuration",
      "description": "获取/设置控制器功能配置位掩码。",
      "description_en": "Get/set the controller feature configuration bitmask."
    },
    {
      "action_name": "auto-dhcp_mode",
      "description": "获取/设置 DHCP 模式。",
      "description_en": "Get/set DHCP mode."
    },
    {
      "action_name": "auto-error_code",
      "description": "获取当前错误代码。",
      "description_en": "Get the current error code."
    },
    {
      "action_name": "auto-error_code_and_message",
      "description": "获取当前错误代码及错误信息。",
      "description_en": "Get the current error code and error message."
    },
    {
      "action_name": "auto-firmware_version",
      "description": "获取控制器固件版本。",
      "description_en": "Get the controller firmware version."
    },
    {
      "action_name": "auto-gateway",
      "description": "获取/设置网关地址。",
      "description_en": "Get/set the gateway address."
    },
    {
      "action_name": "auto-hostname",
      "description": "获取/设置控制器主机名。",
      "description_en": "Get/set the controller hostname."
    },
    {
      "action_name": "auto-ip_address",
      "description": "获取/设置 IP 地址。",
      "description_en": "Get/set the IP address."
    },
    {
      "action_name": "auto-mac_address",
      "description": "获取 MAC 地址。",
      "description_en": "Get the MAC address."
    },
    {
      "action_name": "auto-multiple_controllers",
      "description": "获取/设置是否启用多控制器模式。",
      "description_en": "Get/set whether multi-controller mode is enabled."
    },
    {
      "action_name": "auto-name",
      "description": "获取控制器名称。",
      "description_en": "Get the controller name."
    },
    {
      "action_name": "auto-netmask",
      "description": "获取/设置子网掩码。",
      "description_en": "Get/set the subnet mask."
    },
    {
      "action_name": "auto-scan_controllers",
      "description": "查询 RS-485 网络中控制器的地址映射。",
      "description_en": "Query the controller address map on the RS-485 network."
    },
    {
      "action_name": "auto-scan_done",
      "description": "获取控制器扫描是否完成。",
      "description_en": "Get whether the controller scan is complete."
    },
    {
      "action_name": "auto-abort_motion",
      "description": "立即停止所有正在进行的运动。",
      "description_en": "Immediately stop all motion in progress."
    },
    {
      "action_name": "auto-motor_check",
      "description": "检测已连接电机并设置相应参数。",
      "description_en": "Detect connected motors and set the corresponding parameters."
    },
    {
      "action_name": "auto-scan",
      "description": "扫描 RS-485 网络并自动分配控制器地址。",
      "description_en": "Scan the RS-485 network and automatically assign controller addresses."
    },
    {
      "action_name": "auto-purge",
      "description": "清除控制器非易失性存储并恢复出厂设置。",
      "description_en": "Clear the controller non-volatile memory and restore factory settings."
    },
    {
      "action_name": "auto-recall_parameters",
      "description": "调用已保存的参数组。",
      "description_en": "Recall a saved parameter set."
    },
    {
      "action_name": "auto-reset",
      "description": "软复位控制器。",
      "description_en": "Soft-reset the controller."
    },
    {
      "action_name": "auto-save_settings",
      "description": "将当前设置保存到非易失性存储器。",
      "description_en": "Save the current settings to non-volatile memory."
    },
    {
      "action_name": "auto-query",
      "description": "发送原始 ASCII 查询并读取设备响应。",
      "description_en": "Send a raw ASCII query and read the device response."
    },
    {
      "action_name": "auto-acceleration",
      "description": "获取/设置电机轴加速度。",
      "description_en": "Get/set the axis acceleration."
    },
    {
      "action_name": "auto-home_position",
      "description": "获取/设置电机轴参考原点位置。",
      "description_en": "Get/set the axis home position."
    },
    {
      "action_name": "auto-is_stopped",
      "description": "获取电机轴是否已停止运动。",
      "description_en": "Get whether the axis motion is stopped."
    },
    {
      "action_name": "auto-motor_type",
      "description": "获取/设置电机轴电机类型。",
      "description_en": "Get/set the axis motor type."
    },
    {
      "action_name": "auto-move_absolute",
      "description": "将电机轴移动到绝对位置。",
      "description_en": "Move the axis to an absolute position."
    },
    {
      "action_name": "auto-move_relative",
      "description": "使电机轴按相对位移量移动。",
      "description_en": "Move the axis by a relative increment."
    },
    {
      "action_name": "auto-position",
      "description": "获取电机轴当前位置。",
      "description_en": "Get the current axis position."
    },
    {
      "action_name": "auto-velocity",
      "description": "获取/设置电机轴速度。",
      "description_en": "Get/set the axis velocity."
    },
    {
      "action_name": "auto-move_indefinite",
      "description": "使电机轴沿指定方向连续运动，直到停止命令发出。",
      "description_en": "Move the axis continuously in a specified direction until stopped."
    },
    {
      "action_name": "auto-sendcmd",
      "description": "向控制器发送原始命令。",
      "description_en": "Send a raw command to the controller."
    }
  ]
}

